+  throw new Error(`${message} at ${position(source, offset)}`);
+}
+
+function parse(template: string): Node[] {
+  const root: Node[] = [];
+  const stack: Array<Extract<Node, { type: "if" | "each" }>> = [];
+  let current = root;
+  let cursor = 0;
+
+  while (cursor < template.length) {
+    const start = template.indexOf("{{", cursor);
+    if (start === -1) {
+      if (cursor < template.length) current.push({ type: "text", value: template.slice(cursor) });
+      break;
+    }
+    if (start > cursor) current.push({ type: "text", value: template.slice(cursor, start) });
+
+    const triple = template.startsWith("{{{", start);
+    const close = triple ? "}}}" : "}}";
+    const end = template.indexOf(close, start + (triple ? 3 : 2));
+    if (end === -1) fail(template, start, "Unclosed tag");
+    const raw = template.slice(start + (triple ? 3 : 2), end).trim();
+    const next = end + close.length;
+
+    if (triple) {
+      if (!raw) fail(template, start, "Empty interpolation");
+      current.push({ type: "variable", path: raw, escaped: false });
+    } else if (raw.startsWith("!")) {
+      // Comments intentionally do not create output.
+    } else if (raw.startsWith("#")) {
+      const match = /^#(if|each)\s+(.+)$/.exec(raw);
+      if (!match) fail(template, start, "Unknown or malformed block");
+      const node: Extract<Node, { type: "if" | "each" }> = {
+        type: match[1] as "if" | "each", path: match[2].trim(), children: [], alternate: [], hasElse: false,
+      };
+      current.push(node);
+      stack.push(node);
+      current = node.children;
+    } else if (raw === "else") {
+      const block = stack.at(-1);
+      if (!block) fail(template, start, "Else outside a block");
+      if (block.hasElse) fail(template, start, "Duplicate else");
+      block.hasElse = true;
+      current = block.alternate;
+    } else if (raw.startsWith("/")) {
+      const name = raw.slice(1).trim();
+      const block = stack.at(-1);
+      if (!block || (name !== "if" && name !== "each") || block.type !== name) {
+        fail(template, start, "Mismatched or unexpected closing block");
+      }
+      stack.pop();
+      current = stack.length ? (stack.at(-1)!.hasElse ? stack.at(-1)!.alternate : stack.at(-1)!.children) : root;
+    } else {
