+  if (path === "@index") return context.index;
+  const parts = path.split(".");
+  let value: unknown = context.value;
+  for (const part of parts) {
+    if (value !== null && typeof value === "object" && part in value) value = (value as Record<string, unknown>)[part];
+    else {
+      value = context.root;
+      for (const rootPart of parts) {
+        if (value !== null && typeof value === "object" && rootPart in value) value = (value as Record<string, unknown>)[rootPart];
+        else return undefined;
+      }
+      return value;
+    }
+  }
+  return value;
+}
+
+function truthy(value: unknown): boolean {
+  return !(value === false || value === null || value === undefined || value === 0 || value === "" || (Array.isArray(value) && value.length === 0));
+}
+
+function scalar(value: unknown): string {
+  if (value === null || value === undefined) return "";
+  if (typeof value === "object" || typeof value === "function") throw new Error("Cannot render an object or function as scalar text");
+  return String(value);
+}
+
+function escapeHtml(value: string): string {
+  return value.replace(/[&<>"']/g, (char) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[char]!);
+}
+
+function renderNodes(nodes: Node[], context: Context): string {
+  return nodes.map((node) => {
+    if (node.type === "text") return node.value;
+    if (node.type === "variable") {
+      const value = scalar(lookup(node.path, context));
+      return node.escaped ? escapeHtml(value) : value;
+    }
+    const value = lookup(node.path, context);
+    if (node.type === "if") return renderNodes(truthy(value) ? node.children : node.alternate, context);
+    if (!Array.isArray(value)) return renderNodes(node.alternate, context);
+    if (value.length === 0) return renderNodes(node.alternate, context);
+    return value.map((item, index) => renderNodes(node.children, { ...context, value: item, index })).join("");
+  }).join("");
+}
+
+export function render(template: string, data: unknown): string {
+  return renderNodes(parse(template), { root: data, value: data });
+}
