type Node =
  | { type: "text"; value: string }
  | { type: "variable"; path: string; escaped: boolean }
  | { type: "if" | "each"; path: string; children: Node[]; alternate: Node[]; hasElse: boolean };

type Context = { root: unknown; value: unknown; index?: number };

function position(source: string, offset: number): string {
  const before = source.slice(0, offset);
  const line = before.split("\n").length;
  const column = offset - before.lastIndexOf("\n");
  return `line ${line}, column ${column}`;
}

function fail(source: string, offset: number, message: string): never {
  throw new Error(`${message} at ${position(source, offset)}`);
}

function parse(template: string): Node[] {
  const root: Node[] = [];
  const stack: Array<Extract<Node, { type: "if" | "each" }>> = [];
  let current = root;
  let cursor = 0;

  while (cursor < template.length) {
    const start = template.indexOf("{{", cursor);
    if (start === -1) {
      if (cursor < template.length) current.push({ type: "text", value: template.slice(cursor) });
      break;
    }
    if (start > cursor) current.push({ type: "text", value: template.slice(cursor, start) });

    const triple = template.startsWith("{{{", start);
    const close = triple ? "}}}" : "}}";
    const end = template.indexOf(close, start + (triple ? 3 : 2));
    if (end === -1) fail(template, start, "Unclosed tag");
    const raw = template.slice(start + (triple ? 3 : 2), end).trim();
    const next = end + close.length;

    if (triple) {
      if (!raw) fail(template, start, "Empty interpolation");
      current.push({ type: "variable", path: raw, escaped: false });
    } else if (raw.startsWith("!")) {
      // Comments intentionally do not create output.
